size_t WritePSDChannelBlob(const PSDInfo *psd_info, const ImageInfo *image_info, Image *image, Image *next_image, QuantumType quantum_type, unsigned char *compact_pixels, MagickOffsetType size_offset, MagickBooleanType separate, ExceptionInfo *exception) {
  size_t written = 0;

  if (image == (Image *) NULL || image->pixels == (void *) NULL) {
    (void) ThrowMagickException(exception, GetMagickModule(), ImageError, "NullImageReference", "");
    return 0;
  }

  if (next_image == (Image *) NULL) {
    (void) ThrowMagickException(exception, GetMagickModule(), ImageError, "NullImageReference", "");
    return 0;
  }

  if (compact_pixels == (unsigned char *) NULL) {
    (void) ThrowMagickException(exception, GetMagickModule(), ImageError, "NullPixelBuffer", "");
    return 0;
  }

  if (exception == (ExceptionInfo *) NULL) {
    (void) ThrowMagickException(exception, GetMagickModule(), ImageError, "NullExceptionReference", "");
    return 0;
  }

  if (psd_info == (PSDInfo *) NULL) {
    (void) ThrowMagickException(exception, GetMagickModule(), ImageError, "NullPSDInfoReference", "");
    return 0;
  }

  if (image_info == (ImageInfo *) NULL) {
    (void) ThrowMagickException(exception, GetMagickModule(), ImageError, "NullImageInfoReference", "");
    return 0;
  }

  if (image->columns == 0 || image->rows == 0) {
    (void) ThrowMagickException(exception, GetMagickModule(), ImageError, "InvalidImageDimensions", "");
    return 0;
  }

  if (image->depth <= 0) {
    (void) ThrowMagickException(exception, GetMagickModule(), ImageError, "InvalidImageDepth", "");
    return 0;
  }

  if (image->depth > 8) {
    (void) ThrowMagickException(exception, GetMagickModule(), ImageError, "UnsupportedImageDepth", "");
    return 0;
  }

  if (image->depth == 1) {
    /* Handle monochrome images */
    for (size_t y = 0; y < image->rows; y++) {
      size_t row_size = (image->columns + 7) / 8;
      if (row_size > 0) {
        MagickBooleanType status = ExportImagePixels(image, 0, y, image->columns, 1, "RGB", compact_pixels, exception);
        if (!status) {
          (void) ThrowMagickException(exception, GetMagickModule(), ImageError, "ExportImagePixelsFailed", "");
          return 0;
        }
        written += row_size;
      }
    }
  }
  else {
    /* Handle RLE or Zip compression */
    for (size_t y = 0; y < image->rows; y++) {
      size_t row_size = image->columns * (image->depth / 8);
      if (row_size > 0) {
        MagickBooleanType status = ExportImagePixels(image, 0, y, image->columns, 1, "RGB", compact_pixels, exception);
        if (!status) {
          (void) ThrowMagickException(exception, GetMagickModule(), ImageError, "ExportImagePixelsFailed", "");
          return 0;
        }
        written += row_size;
      }
    }
  }

  return written;
}
